from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
prime_hub = PrimeHub()
back_motor = Motor(Port.A, Direction.CLOCKWISE)
Left_wheel = Motor(Port.B, Direction.COUNTERCLOCKWISE)
front_motor = Motor(Port.D, Direction.CLOCKWISE)
right_wheel = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(Left_wheel, right_wheel, 62, 187)

def canopy():
    # R Left side of curved black piece is aligned with the with the gray line above the 3rd black line from the right hand corner of the board
    # A bulldozer
    # P 2
    drive_base.straight(55)
    drive_base.turn(-54)
    drive_base.straight(635)
    drive_base.turn(18)
    drive_base.straight(-15)
    front_motor.run_angle(500, 20)
    front_motor.run_angle(500, -20)
    drive_base.straight(-20)
    front_motor.run_angle(187, 100)
    wait(800)
    drive_base.straight(15)
    front_motor.run_angle(150, -85)
    drive_base.straight(-15)
    drive_base.turn(-40)
    drive_base.arc(675, angle=35)
    drive_base.turn(40)
    drive_base.straight(120)
    drive_base.turn(-67)
    drive_base.straight(-74)
    drive_base.turn(20)
    drive_base.straight(275)
    drive_base.turn(-50)
    drive_base.straight(580)
    prime_hub.speaker.beep(1, 1000)


# The main program starts here.
canopy()
